	private static List<String> readAll(CloseableIteration<? extends String> iteration) {
		ArrayList<String> result = new ArrayList<>();
		while (iteration.hasNext()) {
			result.add(iteration.next());
		}
		return result;
	}

	private static void assertMetrics(IndexReportingIterator iterator, int rowsReturned) {
		assertAll("index metrics remain available after the cursor's terminal transition",
				() -> assertEquals("SPOC", iterator.getIndexName()),
				() -> assertEquals(100 + rowsReturned, iterator.getSourceRowsScannedActual()),
				() -> assertEquals(200 + rowsReturned, iterator.getSourceRowsMatchedActual()),
				() -> assertEquals(300 + rowsReturned, iterator.getSourceRowsFilteredActual()));
	}

	private static class TrackingIteration implements CloseableIteration<String> {
		private final List<String> values;
		private int position;
		private int closeCount;

		private TrackingIteration(List<String> values) {
			this.values = values;
		}

		@Override
		public boolean hasNext() {
			return position < values.size();
		}

		@Override
		public String next() {
			if (!hasNext()) {
				throw new NoSuchElementException();
			}
			return values.get(position++);
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closeCount++;
		}

		protected final int rowsReturned() {
			return position;
		}

		protected final int closeCount() {
			return closeCount;
		}
	}

	private static final class TrackingReportingIteration extends TrackingIteration implements IndexReportingIterator {
		private TrackingReportingIteration(List<String> values) {
			super(values);
		}

		@Override
		public String getIndexName() {
			return "SPOC";
		}

		@Override
		public long getSourceRowsScannedActual() {
			return 100 + rowsReturned();
		}

		@Override
		public long getSourceRowsMatchedActual() {
			return 200 + rowsReturned();
		}

		@Override
		public long getSourceRowsFilteredActual() {
			return 300 + rowsReturned();
		}
	}
